package main

import (
	"encoding/json"
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/skill"
	"github.com/spf13/cobra"
)

type skillsUpdateFlags struct {
	all    bool
	output string
}

var skillsUpdateOpts skillsUpdateFlags

var skillsUpdateCmd = &cobra.Command{
	Use:   "update [name]",
	Short: "Update an installed skill to the version pinned by its collection",
	Long: `Reconciles an installed skill against the ref currently pinned by the
registered collections (as seen in the local index cache). If the resolved
ref differs from what's in skills.json, the new content is pulled and
.agents/skills/<name> is replaced.

Run 'intropy skills collection update <alias>' first to refresh the cache if
the upstream collection has been republished.

Pass --all to reconcile every installed skill at once.`,
	Args: cobra.MaximumNArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(skillsUpdateOpts.output, "json", "plain"); err != nil {
			return err
		}
		if len(args) == 0 && !skillsUpdateOpts.all {
			return newUsageErrorf("requires a skill name or --all")
		}
		if len(args) == 1 && skillsUpdateOpts.all {
			return newUsageErrorf("pass either a skill name or --all, not both")
		}

		project, err := skill.FindProject(".")
		if err != nil {
			return fmt.Errorf("update: %w", err)
		}

		client, err := newSkillRegistry()
		if err != nil {
			return fmt.Errorf("update: %w", err)
		}

		installer := skill.NewInstaller(client, skill.NewTarGzExtractor(), project)
		updater := skill.NewUpdater(client, installer, project)

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()

		var names []string
		if skillsUpdateOpts.all {
			manifest, err := project.LoadManifest()
			if err != nil {
				return fmt.Errorf("update: %w", err)
			}
			if len(manifest.Skills) == 0 {
				fmt.Fprintln(cmd.ErrOrStderr(), "No skills installed.")
				return nil
			}
			for _, e := range manifest.Skills {
				names = append(names, e.Name)
			}
		} else {
			names = []string{args[0]}
		}

		var results []skill.UpdateResult
		for _, name := range names {
			result, err := updater.Update(ctx, name)
			if err != nil {
				return fmt.Errorf("update: %w", err)
			}
			results = append(results, result)
			if skillsUpdateOpts.output == "plain" {
				if result.Changed {
					fmt.Fprintf(cmd.ErrOrStderr(), "Updated %s: %s -> %s\n", name, result.OldVersion, result.NewVersion)
				} else {
					fmt.Fprintf(cmd.ErrOrStderr(), "%s already at %s\n", name, result.OldVersion)
				}
			}
		}

		if skillsUpdateOpts.output == "json" {
			enc := json.NewEncoder(cmd.OutOrStdout())
			enc.SetIndent("", "  ")
			return enc.Encode(results)
		}

		changed := 0
		for _, r := range results {
			if r.Changed {
				changed++
			}
		}
		if changed == 0 {
			fmt.Fprintln(cmd.ErrOrStderr(), "Nothing to update.")
		}

		return nil
	},
}

func init() {
	skillsUpdateCmd.Flags().BoolVar(
		&skillsUpdateOpts.all, "all", false,
		"Update every installed skill",
	)
	skillsUpdateCmd.Flags().StringVarP(&skillsUpdateOpts.output, "output", "o", "plain", "output format: plain or json")
	skillsCmd.AddCommand(skillsUpdateCmd)
}

package registry

import (
	"bytes"
	"context"
	"fmt"

	"github.com/opencontainers/go-digest"
	ocispec "github.com/opencontainers/image-spec/specs-go/v1"
	"oras.land/oras-go/v2"
	"oras.land/oras-go/v2/content/memory"
)

// PushArtifact uploads an Artifact to the registry at ref. The ref must
// include a tag.
func (c *Client) PushArtifact(ctx context.Context, ref string, art Artifact) (Descriptor, error) {
	parsed, err := ParseReference(ref)
	if err != nil {
		return Descriptor{}, fmt.Errorf("parse ref: %w", err)
	}
	if parsed.Tag == "" {
		return Descriptor{}, fmt.Errorf("ref must include a tag")
	}

	repo, err := c.repository(parsed)
	if err != nil {
		return Descriptor{}, err
	}

	store := memory.New()

	layers := make([]ocispec.Descriptor, 0, len(art.Layers))
	for _, layer := range art.Layers {
		desc := ocispec.Descriptor{
			MediaType: layer.MediaType,
			Digest:    digest.FromBytes(layer.Data),
			Size:      int64(len(layer.Data)),
		}
		if err := store.Push(ctx, desc, bytes.NewReader(layer.Data)); err != nil {
			return Descriptor{}, fmt.Errorf("stage layer: %w", err)
		}
		layers = append(layers, desc)
	}

	packOpts := oras.PackManifestOptions{
		Layers:              layers,
		ManifestAnnotations: art.Annotations,
	}
	if art.Config.MediaType != "" {
		configDesc := ocispec.Descriptor{
			MediaType: art.Config.MediaType,
			Digest:    digest.FromBytes(art.Config.Data),
			Size:      int64(len(art.Config.Data)),
		}
		if err := store.Push(ctx, configDesc, bytes.NewReader(art.Config.Data)); err != nil {
			return Descriptor{}, fmt.Errorf("stage config: %w", err)
		}
		packOpts.ConfigDescriptor = &configDesc
	}

	manifestDesc, err := oras.PackManifest(ctx, store, oras.PackManifestVersion1_1, art.ArtifactType, packOpts)
	if err != nil {
		return Descriptor{}, fmt.Errorf("pack manifest: %w", err)
	}

	if err := store.Tag(ctx, manifestDesc, parsed.Tag); err != nil {
		return Descriptor{}, fmt.Errorf("tag: %w", err)
	}

	if _, err := oras.Copy(ctx, store, parsed.Tag, repo, parsed.Tag, oras.DefaultCopyOptions); err != nil {
		return Descriptor{}, mapError(err, parsed)
	}

	artifactType := manifestDesc.ArtifactType
	if artifactType == "" {
		artifactType = art.ArtifactType
	}

	return Descriptor{
		MediaType:    manifestDesc.MediaType,
		ArtifactType: artifactType,
		Digest:       manifestDesc.Digest.String(),
		Size:         manifestDesc.Size,
		Annotations:  manifestDesc.Annotations,
	}, nil
}

package oci

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
)

func (c *Client) Pull(ctx context.Context, ref string) (Artifact, error) {
	parsed, err := ParseReference(ref)
	if err != nil {
		return Artifact{}, fmt.Errorf("parse ref: %w", err)
	}

	art, desc, err := c.reg.PullArtifact(ctx, ref)
	if err != nil {
		return Artifact{}, err
	}

	if art.ArtifactType != MediaTypeSkillArtifact {
		return Artifact{}, fmt.Errorf("%w got artifactType %q", ErrNotSkill, art.ArtifactType)
	}

	var cfg Config
	if err := json.Unmarshal(art.Config.Data, &cfg); err != nil {
		return Artifact{}, fmt.Errorf("parse config: %w", err)
	}
	if err := cfg.Validate(); err != nil {
		return Artifact{}, fmt.Errorf("invalid skill config: %w", err)
	}

	if len(art.Layers) != 1 {
		return Artifact{}, fmt.Errorf("%w expected 1 layer, got %d", ErrNotSkill, len(art.Layers))
	}

	layer := art.Layers[0]
	if layer.MediaType != MediaTypeSkillContent {
		return Artifact{}, fmt.Errorf("%w unexpected layer media type %q", ErrNotSkill, layer.MediaType)
	}

	return Artifact{
		Config:  cfg,
		Content: io.NopCloser(bytes.NewReader(layer.Data)),
		Digest:  desc.Digest,
		Tag:     parsed.Tag,
	}, nil
}

