	return LoadLockfile(p.LockfilePath())
}

// SaveLockfile writes the lockfile to skills.lock.json at the project root.
func (p *Project) SaveLockfile(l *Lockfile) error {
	return SaveLockfile(p.LockfilePath(), l)
