package skill

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
)

type Manifest struct {
	Collections []ManifestCollection `json:"collections,omitempty"`
	Skills      []ManifestEntry      `json:"skills"`
}

// §6.3
type ManifestEntry struct {
	Name    string `json:"name"`
	Source  string `json:"source"`
	Version string `json:"version,omitempty"`
}

type ManifestCollection struct {
	Name string `json:"name"`
	Ref  string `json:"ref"`
}

// LoadManifest reads and parses skills.json from path.
func LoadManifest(path string) (*Manifest, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read manifest: %w", err)
	}

	var m Manifest
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&m); err != nil {
		return nil, fmt.Errorf("parse manifest: %w", err)
	}

	if err := m.Validate(); err != nil {
		return nil, fmt.Errorf("validate manifest: %w", err)
	}

	return &m, nil
}

// SaveManifest writes the manifest to path with indented JSON.
// The output is human-edited file material, so prettiness matters.
func SaveManifest(path string, m *Manifest) error {
	if err := m.Validate(); err != nil {
		return fmt.Errorf("invalid manifest: %w", err)
	}

	data, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal manifest: %w", err)
	}
	// Trailing newline; many tools add one and not having it shows up as
	// diff noise in PRs.
	data = append(data, '\n')

	return os.WriteFile(path, data, 0644)
}

func (m *Manifest) Validate() error {
	seen := map[string]struct{}{}
	for i, e := range m.Skills {
		if e.Name == "" {
			return fmt.Errorf("skill[%d]: name is required.", i)
		}
		if e.Source == "" {
			return fmt.Errorf("skill[%d] %q: source is required.", i, e.Name)
		}
		if _, dup := seen[e.Name]; dup {
			return fmt.Errorf("duplicate skill name: %q", e.Name)
		}
		seen[e.Name] = struct{}{}
	}

	return nil
}

package skill

import (
	"context"
	"fmt"

	"github.com/integrio-intropy/intropy-cli/internal/skill/oci"
)

type Adder struct {
	registry  Registry
	installer *Installer
	project   *Project
}

func NewAdder(r Registry, i *Installer, p *Project) *Adder {
	return &Adder{registry: r, installer: i, project: p}
}

type AddOptions struct{}

// Add adds a skill to the project, installs it, and persists both files.
// The ref must include a tag (e.g. ghcr.io/.../skill:1.0.0).
func (a *Adder) Add(ctx context.Context, ref string, opts AddOptions) (LockEntry, error) {
	parsed, err := oci.ParseReference(ref)
	if err != nil {
		return LockEntry{}, fmt.Errorf("parse ref: %w", err)
	}
	if parsed.Tag == "" {
		return LockEntry{}, fmt.Errorf("ref must include a tag")
	}

	artifact, err := a.registry.Pull(ctx, ref)
	if err != nil {
		return LockEntry{}, fmt.Errorf("pull %s: %w", ref, err)
	}

	skillName := artifact.Config.Name
	artifact.Content.Close() // we'll re-pull during installer.Install

	// Check the manifest for duplicates.
	manifest, err := a.project.LoadManifest()
	if err != nil {
		return LockEntry{}, fmt.Errorf("load manifest: %w", err)
	}
	for _, e := range manifest.Skills {
		if e.Name == skillName {
			return LockEntry{}, fmt.Errorf("skill %q is already in the manifest", skillName)
		}
	}

	entry := ManifestEntry{
		Name:    skillName,
		Source:  parsed.Registry + "/" + parsed.Repository,
		Version: parsed.Tag,
	}

	lockEntry, err := a.installer.Install(ctx, entry)
	if err != nil {
		return LockEntry{}, fmt.Errorf("install %s: %w", skillName, err)
	}

	//Append to the manifest
	manifest.Skills = append(manifest.Skills, entry)
	if err := a.project.SaveManifest(manifest); err != nil {
		return LockEntry{}, fmt.Errorf("save manifest: %w", err)
	}

	lockfile, err := a.project.LoadLockfile()
	if err != nil {
		return LockEntry{}, fmt.Errorf("load lockfile: %w", err)
	}
	lockfile.Skills = upsertLockEntry(lockfile.Skills, lockEntry)
	if err := a.project.SaveLockfile(lockfile); err != nil {
		return LockEntry{}, fmt.Errorf("save lockfile: %w", err)
	}

	return lockEntry, nil
}

func upsertLockEntry(entries []LockEntry, e LockEntry) []LockEntry {
	for i, existing := range entries {
		if existing.Name == e.Name {
			entries[i] = e
			return entries
		}
	}

	return append(entries, e)
}

package skill

import (
	"context"
	"fmt"
	"time"
)

// CollectionInstaller registers a collection on a project and installs every
// skill the collection index lists.
type CollectionInstaller struct {
	registry Registry
	adder    *Adder
	project  *Project
}

func NewCollectionInstaller(r Registry, a *Adder, p *Project) *CollectionInstaller {
	return &CollectionInstaller{registry: r, adder: a, project: p}
}

// InstallAll fetches the collection index at ref, registers the collection on
// the project under alias (caching the index for later name lookups), and
// installs every skill the index lists. The index is fetched before
// skills.json is touched, so a bad ref leaves the project unchanged.
func (c *CollectionInstaller) InstallAll(ctx context.Context, alias, ref string) ([]LockEntry, error) {
	index, err := c.registry.PullIndex(ctx, ref)
	if err != nil {
		return nil, fmt.Errorf("fetch index %s: %w", ref, err)
	}

	manifest, err := c.project.LoadManifest()
	if err != nil {
		return nil, fmt.Errorf("load manifest: %w", err)
	}
	registered := false
	for _, col := range manifest.Collections {
		if col.Name == alias {
			registered = true
			break
		}
	}
	if !registered {
		manifest.Collections = append(manifest.Collections, ManifestCollection{Name: alias, Ref: ref})
		if err := c.project.SaveManifest(manifest); err != nil {
			return nil, fmt.Errorf("save manifest: %w", err)
		}
	}
	cached := &CachedCollection{Ref: ref, FetchedAt: time.Now().UTC(), Index: index}
	if err := c.project.SaveCollectionCache(alias, cached); err != nil {
		return nil, fmt.Errorf("cache index: %w", err)
	}

	entries := make([]LockEntry, 0, len(index.Manifests))
	for _, s := range index.Manifests {
		if s.Ref == "" {
			return entries, fmt.Errorf("collection entry %q has no ref annotation", s.Name)
		}
		entry, err := c.adder.Add(ctx, s.Ref, AddOptions{})
		if err != nil {
			return entries, fmt.Errorf("add %s: %w", s.Name, err)
		}
		entries = append(entries, entry)
	}

	return entries, nil
}

package skill

import (
	"archive/tar"
	"compress/gzip"
	"context"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// Extractor unpacks a skill's tar+gzip content layer to one or more destination
// directories. Implementations must:
//   - reject path traversal via ".." in archive entries
//   - reject symlinks
//   - preserve POSIX permissions on regular files
//   - create parent directories as needed
type Extractor interface {
	Extract(ctx context.Context, layer io.Reader, dests []string) error
}

type tarGzExtractor struct{}

func NewTarGzExtractor() Extractor { return tarGzExtractor{} }

func (tarGzExtractor) Extract(ctx context.Context, layer io.Reader, dests []string) error {
	if len(dests) == 0 {
		return errors.New("no destination path")
	}

	primary := dests[0]
	if err := extractTo(layer, primary); err != nil {
		return fmt.Errorf("extract to %s: %w", primary, err)
	}

	for _, dest := range dests[1:] {
		if err := copyTree(primary, dest); err != nil {
			return fmt.Errorf("fan out to %s: %w", dest, err)
		}
	}

	return nil
}

func extractTo(layer io.Reader, dest string) error {
	// Wipe-and-replace
	if err := os.RemoveAll(dest); err != nil {
		return fmt.Errorf("clean %s: %w", dest, err)
	}
	if err := os.MkdirAll(dest, 0755); err != nil {
		return fmt.Errorf("create %s: %w", dest, err)
	}

	gz, err := gzip.NewReader(layer)
	if err != nil {
		return fmt.Errorf("gzip reader: %w", err)
	}
	defer gz.Close()

	tr := tar.NewReader(gz)
	destClean := filepath.Clean(dest) + string(os.PathSeparator)

	for {
		hdr, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return fmt.Errorf("tar next: %w", err)
		}

		// Strip the spec-mandated leading "<skill-name>/" component.
		// The tar is rooted at <skill-name>/, but we install AT
		// .agents/skills/<skill-name>/ — i.e. the destination already
		// includes the skill name, so we drop it from each entry.
		archPath := stripFirstPathComponent(hdr.Name)
		if archPath == "" {
			// The root <skill-name>/ entry itself; nothing to write.
			continue
		}

		target := filepath.Join(dest, archPath)

		// Path traversal defense: after Join, target must still be inside dest.
		if !strings.HasPrefix(filepath.Clean(target)+string(os.PathSeparator), destClean) {
			return fmt.Errorf("illegal path in archive: %s", hdr.Name)
		}

		switch hdr.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(target, fs.FileMode(hdr.Mode).Perm()); err != nil {
				return fmt.Errorf("mkdir %s: %w", target, err)
			}
		case tar.TypeReg:
			if err := writeFile(tr, target, fs.FileMode(hdr.Mode).Perm()); err != nil {
				return fmt.Errorf("write file %s: %w", target, err)
			}
		case tar.TypeSymlink:
			return fmt.Errorf("symlinks not supported in skill archives: %s", hdr.Name)
		default:
			return fmt.Errorf("unsupported tar entry type %v: %s", hdr.Typeflag, hdr.Name)
		}
	}
}

func stripFirstPathComponent(p string) string {
	p = strings.TrimPrefix(p, "./")
	if _, after, ok := strings.Cut(p, "/"); ok {
		return after
	}
	return ""
}

func writeFile(r io.Reader, target string, mode fs.FileMode) error {
	if err := os.MkdirAll(filepath.Dir(target), 0755); err != nil {
		return fmt.Errorf("create parent: %w", err)
	}

	f, err := os.OpenFile(target, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, mode)
	if err != nil {
		return err
	}
	if _, err := io.Copy(f, r); err != nil {
		f.Close()
		return err
	}
	return f.Close()
}

func copyTree(src, dst string) error {
	if err := os.RemoveAll(dst); err != nil {
		return err
	}
	return filepath.WalkDir(src, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(src, path)
		if err != nil {
			return err
		}
		target := filepath.Join(dst, rel)

		info, err := d.Info()
		if err != nil {
			return err
		}

		if d.IsDir() {
			return os.MkdirAll(target, info.Mode().Perm())
		}
		if !info.Mode().IsRegular() {
			return fmt.Errorf("non-regular file in tree: %s", path)
		}
		return copyFile(path, target, info.Mode().Perm())
	})
}

func copyFile(src, dst string, mode fs.FileMode) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()

	out, err := os.OpenFile(dst, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, mode)
	if err != nil {
		return err
	}
	if _, err := io.Copy(out, in); err != nil {
		out.Close()
		return err
	}

	return out.Close()
}

